package dev.oriel.buildlogic;

import java.io.IOException;
import java.nio.file.Path;

/** Local generated bytes are variable; downloaded archives must never use this exclusion. */
public final class GeneratedMinecraftArtifact {
    private GeneratedMinecraftArtifact() {}

    public static String check(Path file, Path repository, String version, String pattern) throws IOException {
        Path actual = file.toRealPath();
        Path expectedRoot = repository.toRealPath();
        if (!actual.startsWith(expectedRoot) || !actual.getFileName().toString().matches(pattern)
                || !actual.getParent().getFileName().toString().equals(version)) {
            return failure(version, file.toString(), expectedRoot + "/**/" + version + "/" + pattern, actual.toString());
        }
        return null;
    }

    public static String failure(String version, String file, String expected, String actual) {
        return "Minecraft " + version + " local Loom exclusion failed: file " + file
                + "; expected " + expected + "; actual " + actual
                + ". Access-widener edits need no checksum update. For an intentional Minecraft/Loom upgrade, review "
                + "gradle/generated-minecraft.json version/file patterns, then run "
                + "./gradlew --offline --no-configuration-cache --dependency-verification off writeDependencyVerification "
                + "and review gradle/verification-metadata.xml; retain downloaded dependency SHA-256 entries.";
    }
}
